const { spawn } = require("child_process");
const p = spawn("playwright-mcp", ["--stdio"], { shell: true });
let buf = "";
const timer = setTimeout(() => { console.log("TIMEOUT"); p.kill(); process.exit(1); }, 15000);
p.stdout.on("data", (d) => {
	buf += d;
	const lines = buf.split("\n").filter((l) => l.trim());
	for (const line of lines) {
		try {
			const m = JSON.parse(line);
			if (m.id === 1) {
				console.log("INIT OK ->", m.result.serverInfo.name, m.result.serverInfo.version);
				clearTimeout(timer);
				p.kill();
				process.exit(0);
			}
		} catch {}
	}
});
p.stderr.on("data", (d) => process.stderr.write("[stderr] " + d));
p.on("error", (e) => { console.log("SPAWN FAIL:", e.message); process.exit(1); });
p.stdin.write('{"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2025-03-26","capabilities":{},"clientInfo":{"name":"t","version":"1"}}}\n');

